CREATE DATABASE IF NOT EXISTS kwhtrack CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kwhtrack;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS homes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,city VARCHAR(80) NOT NULL DEFAULT 'Cartagena',stratum TINYINT UNSIGNED,budget DECIMAL(14,2) NOT NULL,custom_rate DECIMAL(12,4) NOT NULL DEFAULT 1033.32,custom_rate_enabled BOOLEAN NOT NULL DEFAULT FALSE,savings_goal DOUBLE NOT NULL DEFAULT 15,example BOOLEAN NOT NULL DEFAULT FALSE,draft_plan JSON,revision BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id),CHECK(budget>0),CHECK(custom_rate>0),CHECK(stratum BETWEEN 1 AND 6),CHECK(savings_goal BETWEEN 0 AND 50));
CREATE TABLE IF NOT EXISTS devices (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,home_id INT UNSIGNED NOT NULL,client_key VARCHAR(80) NOT NULL,name VARCHAR(80) NOT NULL,category VARCHAR(50) NOT NULL,calculation_mode ENUM('power','monthly') NOT NULL DEFAULT 'power',active BOOLEAN NOT NULL DEFAULT TRUE,monthly_kwh DOUBLE NOT NULL DEFAULT 0,watts DOUBLE NOT NULL,quantity INT UNSIGNED NOT NULL,hours DOUBLE NOT NULL,days TINYINT UNSIGNED NOT NULL,factor DOUBLE NOT NULL DEFAULT 1,FOREIGN KEY(home_id) REFERENCES homes(id),UNIQUE(home_id,client_key),CHECK(watts>0),CHECK(quantity>0),CHECK(hours BETWEEN 0 AND 24),CHECK(days BETWEEN 1 AND 31),CHECK(factor BETWEEN 0 AND 1),CHECK(monthly_kwh>=0));
CREATE TABLE IF NOT EXISTS readings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,home_id INT UNSIGNED NOT NULL,client_key VARCHAR(80) NOT NULL,reading_date DATE NOT NULL,accumulated_kwh DOUBLE NOT NULL,FOREIGN KEY(home_id) REFERENCES homes(id),UNIQUE(home_id,reading_date),UNIQUE(home_id,client_key),CHECK(accumulated_kwh>=0));
CREATE TABLE IF NOT EXISTS bills (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,home_id INT UNSIGNED NOT NULL,client_key VARCHAR(80) NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,kwh DOUBLE NOT NULL,total_paid DECIMAL(15,2) NOT NULL,FOREIGN KEY(home_id) REFERENCES homes(id),UNIQUE(home_id,period_start,period_end),UNIQUE(home_id,client_key),CHECK(period_end>period_start),CHECK(kwh>=0),CHECK(total_paid>=0));
CREATE TABLE IF NOT EXISTS tariffs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(80) NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,rate DECIMAL(12,4) NOT NULL,source_url VARCHAR(1000) NOT NULL,verification ENUM('historical','verified','user') NOT NULL DEFAULT 'historical',conditions_text TEXT NOT NULL,CHECK(rate>0),CHECK(period_end>=period_start));
CREATE TABLE IF NOT EXISTS estimates (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,home_id INT UNSIGNED NOT NULL,tariff_id INT UNSIGNED,rate_snapshot DECIMAL(12,4) NOT NULL,kwh DOUBLE NOT NULL,cost DECIMAL(15,2) NOT NULL,assumptions JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(home_id) REFERENCES homes(id),FOREIGN KEY(tariff_id) REFERENCES tariffs(id));
CREATE TABLE IF NOT EXISTS sessions (token_hash BINARY(32) PRIMARY KEY,user_id INT UNSIGNED NOT NULL,csrf_token CHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id),INDEX(expires_at));
